source("helper.R")
con <- DBI::dbConnect(duckdb::duckdb(shared_home = FALSE)); invisible(DBI::dbExecute(con, "SET arrow_lossless_conversion = true"))
cat("== list of wide ints from duckdb\n")
r <- try_(zuarrow::arrow_to_r(DBI::dbGetQueryArrow(con, "SELECT [9007199254740993::BIGINT, 1] a, [18446744073709551614::UBIGINT] b, [1::HUGEINT] c, {'k': 9007199254740993::BIGINT, 'h': -5::HUGEINT} s"))); str(r)
cat("== metadata reader\n")
g <- function(raw, key) tryCatch(.Call(zuint:::zu_metadata_get_c, raw, key), error = function(e) paste("ERR", conditionMessage(e)))
i4 <- function(x) writeBin(as.integer(x), raw(), size = 4, endian = "little")
ent <- function(k, v) { k <- charToRaw(k); v <- charToRaw(v); c(i4(length(k)), k, i4(length(v)), v) }
many <- function(n, last_k = "key", last_v = "val", count = n) c(i4(count), unlist(lapply(seq_len(n - 1), function(i) ent(sprintf("k%d", i), "v"))), ent(last_k, last_v))
for (n in c(1, 2, 4095, 4096, 4097, 5000)) cat(n, "entries ->", format(g(many(n), "key")), "\n")
cat("count 4097 claimed, key in entry 1:", format(g(c(i4(4097), ent("key","val")), "key")), "\n")
cat("count -1:", format(g(c(i4(-1), ent("key","val")), "key")), "\n")
cat("count 0:", format(g(c(i4(0), ent("key","val")), "key")), "\n")
cat("count 2 but one entry (found first):", format(g(c(i4(2), ent("key","val")), "key")), "\n")
cat("count 2 but one entry (miss):", format(g(c(i4(2), ent("kex","val")), "key")), "\n")
cat("empty raw:", format(g(raw(0), "key")), " 3 bytes:", format(g(raw(3), "key")), " 4 bytes zero:", format(g(raw(4), "key")), "\n")
cat("neg klen:", format(g(c(i4(1), i4(-3), charToRaw("key"), i4(3), charToRaw("val")), "key")), "\n")
cat("neg vlen:", format(g(c(i4(1), i4(3), charToRaw("key"), i4(-1), charToRaw("val")), "key")), "\n")
cat("klen past end:", format(g(c(i4(1), i4(300), charToRaw("key"), i4(3), charToRaw("val")), "key")), "\n")
cat("vlen past end by 1:", format(g(c(i4(1), i4(3), charToRaw("key"), i4(4), charToRaw("val")), "key")), "\n")
cat("vlen exact:", format(g(c(i4(1), i4(3), charToRaw("key"), i4(3), charToRaw("val")), "key")), "\n")
cat("vlen INT_MAX:", format(g(c(i4(1), i4(3), charToRaw("key"), i4(2147483647), charToRaw("val")), "key")), "\n")
cat("klen INT_MAX:", format(g(c(i4(1), i4(2147483647), charToRaw("key"), i4(3), charToRaw("val")), "key")), "\n")
cat("zero-length key entry then key:", format(g(c(i4(2), ent("", "zz"), ent("key", "val")), "key")), "\n")
cat("lookup empty key:", format(g(c(i4(2), ent("", "zz"), ent("key", "val")), "")), "\n")
cat("prefix first:", format(g(c(i4(2), ent("ke", "no"), ent("key", "val")), "key")), " longer first:", format(g(c(i4(2), ent("keyy", "no"), ent("key", "val")), "key")), "\n")
cat("lookup prefix:", format(g(c(i4(1), ent("key", "val")), "ke")), "\n")
cat("zero-length value:", deparse(g(c(i4(1), ent("key", "")), "key")), "\n")
cat("repeated:", format(g(c(i4(2), ent("key", "one"), ent("key", "two")), "key")), "\n")
cat("trailing truncated after hit:", format(g(c(i4(2), ent("key", "one"), i4(99)), "key")), "\n")
cat("value with NUL:", format(g(c(i4(1), i4(3), charToRaw("key"), i4(3), as.raw(c(97,0,98))), "key")), "\n")
cat("key with NUL 'ke\\0y' lookup 'ke':", format(g(c(i4(1), i4(4), as.raw(c(107,101,0,121)), i4(1), charToRaw("v")), "ke")), "\n")
cat("bad args:", format(g("x", "key")), format(g(raw(4), 1L)), format(g(raw(4), character(0))), format(g(raw(4), NA_character_)), "\n")
cat("truncated header for entry (only 2 bytes of klen):", format(g(c(i4(1), raw(2)), "key")), "\n")
cat("vlen header truncated:", format(g(c(i4(1), i4(3), charToRaw("key"), raw(3)), "key")), "\n")
